{"title":"Rule Burst Heatmap (z-score)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {
    "text": "Color = volume z-score against each rule's own baseline. Brighter = burst / volume anomaly.",
    "anchor": "start",
    "color": "#69707D",
    "fontSize": 11,
    "fontWeight": "normal",
    "offset": 6
  },
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "timestamp",
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "rules": {
            "terms": {
              "field": "rule.description",
              "size": 12,
              "order": {
                "_count": "desc"
              }
            },
            "aggs": {
              "t": {
                "date_histogram": {
                  "field": "timestamp",
                  "interval": {
                    "%autointerval%": true
                  },
                  "min_doc_count": 0
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.rules.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.key",
      "as": "rule"
    },
    {
      "calculate": "datum.doc_count",
      "as": "total"
    },
    {
      "calculate": "datum.t.buckets",
      "as": "slots"
    },
    {
      "flatten": [
        "slots"
      ],
      "as": [
        "b"
      ]
    },
    {
      "calculate": "datum.b.key",
      "as": "ts"
    },
    {
      "calculate": "datum.b.doc_count",
      "as": "count"
    },
    {
      "joinaggregate": [
        {
          "op": "mean",
          "field": "count",
          "as": "mu"
        },
        {
          "op": "stdev",
          "field": "count",
          "as": "sd"
        }
      ],
      "groupby": [
        "rule"
      ]
    },
    {
      "calculate": "(datum.count - datum.mu) / (datum.sd + 1)",
      "as": "z"
    }
  ],
  "mark": {
    "type": "rect",
    "tooltip": true,
    "stroke": "#FFFFFF",
    "strokeWidth": 0.4
  },
  "encoding": {
    "x": {
      "field": "ts",
      "type": "ordinal",
      "title": null,
      "sort": "ascending",
      "axis": {
        "labelExpr": "timeFormat(toNumber(datum.value), '%d/%m %H:%M')",
        "labelAngle": -40,
        "labelOverlap": "parity",
        "labelColor": "#69707D",
        "tickColor": "#B0B7C3",
        "domainColor": "#B0B7C3"
      }
    },
    "y": {
      "field": "rule",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "total",
        "op": "max",
        "order": "descending"
      },
      "axis": {
        "labelLimit": 280,
        "labelColor": "#343741",
        "tickColor": "#B0B7C3",
        "domainColor": "#B0B7C3"
      }
    },
    "color": {
      "field": "z",
      "type": "quantitative",
      "title": "z-score",
      "scale": {
        "scheme": "inferno",
        "domain": [
          -1,
          4
        ],
        "clamp": true
      },
      "legend": {
        "labelColor": "#69707D",
        "titleColor": "#343741"
      }
    },
    "tooltip": [
      {
        "field": "rule",
        "type": "nominal",
        "title": "Rule"
      },
      {
        "field": "ts",
        "type": "temporal",
        "title": "Interval",
        "format": "%Y-%m-%d %H:%M"
      },
      {
        "field": "count",
        "type": "quantitative",
        "title": "Alerts in interval",
        "format": ","
      },
      {
        "field": "mu",
        "type": "quantitative",
        "title": "Baseline (mean)",
        "format": ".0f"
      },
      {
        "field": "sd",
        "type": "quantitative",
        "title": "Std dev",
        "format": ".0f"
      },
      {
        "field": "z",
        "type": "quantitative",
        "title": "z-score",
        "format": ".2f"
      },
      {
        "field": "total",
        "type": "quantitative",
        "title": "Total in period",
        "format": ","
      }
    ]
  },
  "config": {
    "background": null,
    "view": {
      "stroke": null
    },
    "axis": {
      "grid": false
    },
    "font": "Inter, Helvetica Neue, Helvetica, Arial, sans-serif"
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding",
    "resize": true
  },
  "padding": {
    "top": 10,
    "left": 5,
    "right": 5,
    "bottom": 5
  }
}"}}

